steps.output:
def transform(grid):
    # Fill gaps lying on horizontal or vertical lines between same-color cells,
    # using color 2. Preserve all original cells.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        cells = [c for c in range(w) if grid[r][c] not in (8, 2)]
        for a, b in zip(cells, cells[1:]):
            if b - a > 1:
                for c in range(a + 1, b):
                    if grid[r][c] == 8:
                        out[r][c] = 2
    for c in range(w):
        cells = [r for r in range(h) if grid[r][c] not in (8, 2)]
        for a, b in zip(cells, cells[1:]):
            if b - a > 1:
                for r in range(a + 1, b):
                    if grid[r][c] == 8:
                        out[r][c] = 2
    return out

