# From pair 2: background 3 and markers 8. Expected fill is exactly each 3 between marker positions on a row/column bounded by two markers.
g=[[3]*18 for _ in range(22)]
pts={10:[1,4,8,9,10,11,16],12:[1],14:[16],16:[1,6,7,9,13,16]}
for r,cs in pts.items():
 for c in cs:g[r][c]=8
expected={(10,c) for c in [2,3,5,6,7,12,13,14,15]}|{(r,1) for r in [11]}|{(r,16) for r in [11,12,13,15]}|{(16,c) for c in [2,3,4,5,8,10,11,12,14,15]}
actual=set()
for r in range(22):
 cs=[c for c in range(18) if g[r][c]==8]
 if cs: actual|={(r,c) for c in range(min(cs),max(cs)+1) if g[r][c]==3}
for c in range(18):
 rs=[r for r in range(22) if g[r][c]==8]
 if rs: actual|={(r,c) for r in range(min(rs),max(rs)+1) if g[r][c]==3}
print('matches demo?',actual==expected,'diff',actual^expected)
