def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                for cc in range(c + 1, w):
                    if grid[r][cc] == grid[r][c]:
                        for x in range(c + 1, cc):
                            if grid[r][x] == bg: out[r][x] = 2
    for c in range(w):
        for r in range(h):
            if grid[r][c] != bg:
                for rr in range(r + 1, h):
                    if grid[rr][c] == grid[r][c]:
                        for y in range(r + 1, rr):
                            if grid[y][c] == bg: out[y][c] = 2
    return out

